const item = $input.first();
const data = item.json.body || item.json;

let normalized = {
  channel: 'whatsapp',
  senderId: '',
  senderName: '',
  messageText: '',
  messageId: '',
  timestamp: new Date().toISOString()
};

// ── TWILIO WhatsApp ──
// Twilio envía form-encoded: From, Body, ProfileName, MessageSid
if (data.From && data.From.includes('whatsapp:')) {
  normalized.channel = 'whatsapp';
  normalized.senderId = data.From.replace('whatsapp:', '');
  normalized.senderName = data.ProfileName || 'Prospecto';
  normalized.messageText = data.Body || '';
  normalized.messageId = data.MessageSid || '';

// ── META WhatsApp Business API ──
} else if (data.object === 'whatsapp_business_account' || data.entry?.[0]?.changes?.[0]?.field === 'messages') {
  const entry = data.entry?.[0]?.changes?.[0]?.value;
  const msg = entry?.messages?.[0];
  // Ignorar eventos de estado (delivered, read, sent)
  if (!msg || msg.type === 'status') return [];
  normalized.channel = 'whatsapp';
  normalized.senderId = msg?.from || '';
  normalized.senderName = entry?.contacts?.[0]?.profile?.name || 'Prospecto';
  normalized.messageText = msg?.text?.body || msg?.interactive?.button_reply?.title || '';
  normalized.messageId = msg?.id || '';

// ── DATOS DE PRUEBA DIRECTOS ──
} else if (data.senderId || data.messageText) {
  normalized = { ...normalized, ...data };
}

// Si no hay texto útil no procesamos (evita loops por status updates)
if (!normalized.messageText.trim()) return [];

return [{ json: normalized }];

const msg = $('Normalizar Mensaje').first().json;
const sheetData = $input.first().json;

// Construir contexto del prospecto con valores defensivos
let prospectContext = {
  isNewProspect: true,
  senderId: msg.senderId,
  senderName: msg.senderName,
  businessName: 'tu clínica',
  contactName: msg.senderName,
  phone: msg.senderId,
  conversationStage: 'esperando_respuesta_inicial',
  conversationHistory: [],
  openingUsed: 'A',
  demoDate: '',
  notes: ''
};

// Si existe en la base de datos, cargar datos
if (sheetData && sheetData.sender_id) {
  prospectContext.isNewProspect = false;
  prospectContext.businessName = sheetData.business_name || prospectContext.businessName;
  prospectContext.contactName = sheetData.contact_name || msg.senderName;
  prospectContext.conversationStage = sheetData.conversation_stage || 'esperando_respuesta_inicial';
  prospectContext.openingUsed = sheetData.opening_used || 'A';
  prospectContext.demoDate = sheetData.demo_date || '';
  prospectContext.notes = sheetData.notes || '';

  // Cargar historial de conversación (JSON guardado en Sheets)
  try {
    prospectContext.conversationHistory = JSON.parse(sheetData.conversation_history || '[]');
  } catch(e) {
    prospectContext.conversationHistory = [];
  }
}

// Agregar el mensaje actual al historial
prospectContext.conversationHistory.push({
  role: 'user',
  content: msg.messageText,
  timestamp: msg.timestamp
});

// Mantener solo los últimos 12 mensajes para no sobrecargar el contexto
if (prospectContext.conversationHistory.length > 12) {
  prospectContext.conversationHistory = prospectContext.conversationHistory.slice(-12);
}

return [{ json: { ...msg, prospectContext } }];

const aiResponse = $json.message.content;
const marker = 'DEMO_AGENDADA:';
const markerIndex = aiResponse.indexOf(marker);

if (markerIndex === -1) {
  return [{ json: { ...($json), parseError: true } }];
}

// Extraer la línea del marcador
const afterMarker = aiResponse.substring(markerIndex + marker.length);
const lineEnd = afterMarker.indexOf('\n');
const demoLine = lineEnd !== -1 ? afterMarker.substring(0, lineEnd) : afterMarker;

const parts = demoLine.split('|').map(p => p.trim());
const [contactName, businessName, dateTimeStr, phone] = parts;

// Parsear fecha DD/MM/YYYY HH:mm
let startDateTime, endDateTime;
try {
  if (dateTimeStr && dateTimeStr.match(/\d{2}\/\d{2}\/\d{4}/)) {
    const [datePart, timePart] = dateTimeStr.split(' ');
    const [day, month, year] = datePart.split('/');
    const [hour, minute] = (timePart || '16:00').split(':');
    startDateTime = new Date(
      parseInt(year), parseInt(month) - 1, parseInt(day),
      parseInt(hour), parseInt(minute || '0')
    );
  } else {
    // Fallback: mañana a las 4pm
    startDateTime = new Date();
    startDateTime.setDate(startDateTime.getDate() + 1);
    startDateTime.setHours(16, 0, 0, 0);
  }
  // Demo de 20 minutos
  endDateTime = new Date(startDateTime.getTime() + 20 * 60 * 1000);
} catch(e) {
  startDateTime = new Date();
  startDateTime.setDate(startDateTime.getDate() + 1);
  startDateTime.setHours(16, 0, 0, 0);
  endDateTime = new Date(startDateTime.getTime() + 20 * 60 * 1000);
}

// Extraer solo el mensaje de confirmación (después del marcador)
const afterCode = lineEnd !== -1 ? afterMarker.substring(lineEnd + 1).trim() : '';
// Eliminar también la línea ETAPA_ACTUALIZADA del mensaje al cliente
const cleanMessage = afterCode.replace(/ETAPA_ACTUALIZADA:[^\n]*/g, '').trim();

const startFormatted = startDateTime.toLocaleString('es-MX', { timeZone: 'America/Mexico_City' });

return [{
  json: {
    ...($json),
    demoData: {
      contactName: contactName || 'Prospecto',
      businessName: businessName || 'Clínica Dental',
      phone: phone || '',
      startDateTime: startDateTime.toISOString(),
      endDateTime: endDateTime.toISOString(),
      startDateTimeFormatted: startFormatted,
      summary: `Demo IA — ${businessName} — ${contactName}`,
      description: `Contacto: ${contactName}\nNegocio: ${businessName}\nTeléfono: ${phone}\nAgendado por: Sofia (Bot Prospector)\nDuración: 20 minutos`
    },
    cleanConfirmationMessage: cleanMessage
  }
}];

const msg = $('Normalizar Mensaje').first().json;
const context = $('Construir Contexto Prospecto').first().json.prospectContext;
const aiRaw = $('Sofia — Agente IA').first().json.message.content;

// Extraer la nueva etapa del marcador ETAPA_ACTUALIZADA
let newStage = context.conversationStage;
const stageMatch = aiRaw.match(/ETAPA_ACTUALIZADA:([\w_]+)/);
if (stageMatch && stageMatch[1]) {
  newStage = stageMatch[1].trim();
}

// Intentar obtener datos de demo si fue agendada
let demoData = null;
let calendarEventId = '';
try {
  demoData = $('Parsear Datos de Demo').first()?.json?.demoData;
  calendarEventId = $('Crear Demo en Google Calendar').first()?.json?.id || '';
} catch(e) {
  // No hubo demo en este turno — es flujo normal
}

// Actualizar historial con respuesta del bot
const updatedHistory = [...context.conversationHistory, {
  role: 'assistant',
  content: aiRaw.replace(/DEMO_AGENDADA:[^\n]*/g, '').replace(/ETAPA_ACTUALIZADA:[^\n]*/g, '').trim(),
  timestamp: new Date().toISOString()
}].slice(-12);

const rowData = {
  sender_id: msg.senderId,
  business_name: demoData?.businessName || context.businessName,
  contact_name: demoData?.contactName || context.contactName,
  phone: msg.senderId,
  status: newStage === 'demo_confirmada' ? 'demo_confirmada' : 'en_conversacion',
  conversation_stage: newStage,
  conversation_history: JSON.stringify(updatedHistory),
  last_message: msg.messageText,
  last_message_date: new Date().toISOString(),
  demo_date: demoData?.startDateTimeFormatted || context.demoDate,
  demo_calendar_id: calendarEventId || '',
  opening_used: context.openingUsed,
  notes: context.notes,
  updated_at: new Date().toISOString()
};

return [{ json: { rowData, demoData, msg, context, aiRaw } }];

const ctx = $('Preparar Actualización Prospecto').first().json;
const demoData = ctx.demoData;
const senderName = ctx.context.contactName || ctx.msg.senderName;
const aiRaw = ctx.aiRaw;

let responseMessage = '';

if (demoData) {
  // Ruta con demo agendada: usar el mensaje de confirmación del AI (después del marcador)
  const markerIndex = aiRaw.indexOf('DEMO_AGENDADA:');
  let confirmationMsg = '';
  if (markerIndex !== -1) {
    const afterMarker = aiRaw.substring(markerIndex);
    const lineEnd = afterMarker.indexOf('\n');
    if (lineEnd !== -1) {
      confirmationMsg = afterMarker.substring(lineEnd + 1)
        .replace(/ETAPA_ACTUALIZADA:[^\n]*/g, '')
        .trim();
    }
  }
  // Si el AI no escribió confirmación, construir una de respaldo
  if (!confirmationMsg) {
    confirmationMsg = `Perfecto ${senderName} ✅ Ya quedó agendada tu demo el ${demoData.startDateTimeFormatted}.\n\nEs una sesión de 20 minutos directamente con el dueño. Te mando el link de Zoom en un momento. ¡Hasta entonces!`;
  }
  responseMessage = confirmationMsg;
} else {
  // Ruta normal: limpiar marcadores del mensaje
  responseMessage = aiRaw
    .replace(/DEMO_AGENDADA:[^\n]*/g, '')
    .replace(/ETAPA_ACTUALIZADA:[^\n]*/g, '')
    .trim();
}

// Escapar caracteres especiales para TwiML/XML
const xmlEscape = (str) => str
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/"/g, '&quot;');

return [{ json: { message: responseMessage, messageXml: xmlEscape(responseMessage), senderId: ctx.msg.senderId } }];
